class Solution {
public:
    int change(int amount, vector<int>& coins) {
        vector<unsigned long long> ways(amount + 1, 0);
        ways[0] = 1;
        for (int c = 0; c < (int)coins.size(); c++) {
            for (int a = coins[c]; a <= amount; a++) ways[a] += ways[a - coins[c]];
        }
        return ways[amount];
    }
};
